function commands(){modal('Найти действие',`<div class="search-wrap">${icon('search')}<input id="command-query" placeholder="Раздел, настройка или действие…" aria-label="Поиск действий" autofocus></div><div id="command-list" style="margin-top:15px"></div>`,null,'',true);modalContext='commands';renderCommands('');setTimeout(()=>$('#command-query')?.focus(),30);}
