function unlock(){modal('Открыть базу',`${field('db-path','Файл базы','D:\\WinUp\\vault.kdbx','text',true)}<div style="margin-top:15px">${field('password','Пароль','','password',true)}</div><div class="toolbar" style="margin-top:15px">${btn('hello-demo','Войти по Windows Hello','fingerprint')}${btn('pin-demo','Войти по PIN','key')}</div><details><summary>Ключ-файл или восстановление</summary>${field('keyfile','Путь к ключ-файлу','','text',true)}${btn('db-recovery','Код восстановления','shield','small')}</details><div class="notice">Подходит любой непустой пароль. Windows Hello и PIN смоделированы.</div>`,()=>{if(!value('password'))return error('Введите учебный пароль');state.vaultLocked=false;done('Учебная база открыта');},'Открыть');}
