  kdf:()=>modal('Защита от подбора пароля',`<p class="modal-description">Параметры Argon2 замедляют подбор и открытие базы. В макете настройка не влияет на реальное шифрование.</p><div class="form-grid">${dropdown('memory','Память',['64 МБ','128 МБ','256 МБ','512 МБ'],'128 МБ')}${dropdown('iterations','Проходы',['2','3','4','6'],'3')}</div>`,()=>done('Учебные параметры сохранены')),
  hotkey:()=>modal('Автоввод и горячая клавиша',`${field('hotkey','Сочетание клавиш',state.settings.hotkey,'text',true)}${checkbox('enabled','Включить горячую клавишу',true)}<div class="notice">HTML-макет не перехватывает системные клавиши. Ctrl+K открывает поиск действий только на этой странице.</div>`,()=>{state.settings.hotkey=value('hotkey');done('Сочетание сохранено в макете');}),
