function setTheme(t){document.documentElement.dataset.theme=t;state.settings.theme=t;toast(t==='dark'?'Тёмная тема':'Светлая тема');}
function toggleChecks(items){let on=items.some(i=>!state.checked.has(i.id));items.forEach(i=>on?state.checked.add(i.id):state.checked.delete(i.id));render();}
const requiresVault=new Set(['account-add','account-edit','account-delete','account-more','import','export','templates','merge','addresses','groups','fields','attachments','references','autotype','recovery','record-history','trash','bulk','otp-add','otp-edit','otp-import','passkey-add','passkey-login','passkey-delete','passkey-details','copy-password','copy-login','copy-extra','copy-otp','pin']);
function dispatch(action,e){closeMenu();if(requiresVault.has(action)&&state.vaultLocked){toast('Сначала откройте базу',true);unlock();return;}if(!A[action]){console.error('Unimplemented action: '+action);toast('Действие не подключено: '+action,true);return;}try{A[action](e||document.createElement('button'));}catch(ex){console.error(ex);toast('Не удалось выполнить действие: '+ex.message,true);}}
document.addEventListener('click',event=>{if(event.target.closest('input,select,textarea'))return;let e=event.target.closest('[data-action]');if(e&&!e.disabled){event.preventDefault();dispatch(e.dataset.action,e);}else if(!event.target.closest('.popover'))closeMenu();});
document.addEventListener('input',event=>{let e=event.target;if(e.id==='search'){let pos=e.selectionStart;state.query=e.value;render();let n=$('#search');n.focus();n.setSelectionRange(pos,pos);}if(e.id==='template-query'){templateQuery=e.value;renderTemplates();}if(e.id==='command-query')renderCommands(e.value);if(e.id==='gen-length')regenerate();});
document.addEventListener('change',event=>{let e=event.target;if(e.id==='category-filter'){state.category=e.value;render();}if(e.id==='type-filter'){state.type=e.value;render();}if(e.id==='template-category'){templateCategory=e.value;renderTemplates();}
  if(e.dataset.check){e.checked?state.checked.add(e.dataset.check):state.checked.delete(e.dataset.check);render();}if(e.hasAttribute('data-check-all')){let on=e.checked;filteredAccounts().forEach(a=>on?state.checked.add(a.id):state.checked.delete(a.id));render();}
  for(let key of ['packageCheck','installerCheck'])if(e.dataset[key]){e.checked?state.checked.add(e.dataset[key]):state.checked.delete(e.dataset[key]);}
  if(e.dataset.fileCheck){e.checked?state.fileSelection.add(e.dataset.fileCheck):state.fileSelection.delete(e.dataset.fileCheck);}if(e.hasAttribute('data-file-all'))fileItems().forEach(f=>e.checked?state.fileSelection.add(f.id):state.fileSelection.delete(f.id));
  if(e.dataset.setting){let v=e.type==='checkbox'?e.checked:e.value;if(e.dataset.setting==='browser')state.browser=v;else state.settings[e.dataset.setting]=v;log('Изменена учебная настройка: '+e.dataset.setting);}
  if(e.name==='extension-browser')extension(e.value);if(e.name==='type'&&modalContext==='account')stashDraft();if(['numbers','symbols','uppercase'].includes(e.name)&&modalContext?.startsWith('generator'))regenerate();
});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();commands();}else if(event.key==='Escape'){closeMenu();}else if(event.key==='Enter'&&event.target.matches('[role="button"][data-action]')){event.preventDefault();dispatch(event.target.dataset.action,event.target);}else if(event.key==='Enter'&&event.target.matches('input')&&$('#modal').open&&modalSubmit){event.preventDefault();modalSubmit();}});
$('#modal').addEventListener('close',()=>{if($('#modal').open)return;if(modalContext==='task'){taskEpoch++;clearTimeout(taskTimer);}modalSubmit=null;modalContext=null;});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
document.addEventListener('dragover',e=>{let drop=e.target.closest('#file-drop');if(drop){e.preventDefault();drop.classList.add('drag');}});document.addEventListener('dragleave',e=>{let drop=e.target.closest('#file-drop');if(drop)drop.classList.remove('drag');});document.addEventListener('drop',e=>{let drop=e.target.closest('#file-drop');if(drop){e.preventDefault();addFileMetadata([...e.dataTransfer.files]);}});
window.addEventListener('hashchange',()=>{let section=location.hash.slice(1);if(sections[section]&&section!==state.section)navigate(section);});
if(sections[location.hash.slice(1)])state.section=location.hash.slice(1);
hydrate();render();setInterval(tickOtp,500);
